record.field:
# Update quota usage for all active clients
clients = env['saas_portal.client'].search([('state', '=', 'open')])
for client in clients:
    if client.users_len:
        client.update_quota_usage('users', client.users_len)
    if client.file_storage or client.db_storage:
        total_storage = (client.file_storage or 0) + (client.db_storage or 0)
        client.update_quota_usage('storage', total_storage)
